function ranksFor(spec: SpecId, pool: PoolId): string[] {
  return Object.keys(RUNS)
    .filter((id) => id.startsWith(`${spec}|${pool}|`))
    .sort((a, b) => Number(RUNS[b].dps) - Number(RUNS[a].dps) || Number(RUNS[b].farm) - Number(RUNS[a].farm) || Number(a.split("|")[2]) - Number(b.split("|")[2]));
}

function GameText({ text }: { text: string }) {
  return (
    <Text size="small" style={{ whiteSpace: "pre-wrap" }}>
      {text}
    </Text>
  );
}

export default function PaladinSims() {
  const [spec, setSpec] = useCanvasState<SpecId>("pala-fight-spec", "retribution");
  const [pool, setPool] = useCanvasState<PoolId>("pala-fight-pool", "mixed");
  const [rank, setRank] = useCanvasState<string>("pala-fight-rank", "1");
  const chosenSpec: SpecId = spec === "protection" ? "protection" : "retribution";
  const available = POOLS.filter(([id]) => ranksFor(chosenSpec, id).length > 0);
  const chosenPool: PoolId = available.some(([id]) => id === pool) ? pool : "mixed";
  const ranks = ranksFor(chosenSpec, chosenPool);
  const chosenRank = ranks.some((id) => id.endsWith(`|${rank}`)) ? rank : "1";
  const run = RUNS[`${chosenSpec}|${chosenPool}|${chosenRank}`];
  const specTitle = chosenSpec === "retribution" ? "Retribution" : "Protection";
  const [catalog, setCatalog] = useCanvasState<"picked" | "all">("pala-fight-catalog", "picked");
  const pickedTalents = (run.stats.find((row) => row[0] === "Таланты")?.[1] ?? "").split(", ").filter(Boolean);
  const pickedGlyphs = (run.stats.find((row) => row[0] === "Глифы")?.[1] ?? "").split(", ").filter(Boolean);
  const dpsOf = (entry: Entry) => (chosenSpec === "retribution" ? entry.ret : entry.prot);
  const talentRows = (catalog === "picked" ? TALENTS.filter((entry) => pickedTalents.includes(entry.name)) : TALENTS)
    .slice()
    .sort((a, b) => dpsOf(b) - dpsOf(a));
  const glyphRows = (catalog === "picked" ? GLYPHS.filter((entry) => pickedGlyphs.includes(entry.name)) : GLYPHS)
    .slice()
    .sort((a, b) => dpsOf(b) - dpsOf(a));
  const itemScore = (name: string) => ITEM_DPS[name]?.[chosenSpec === "retribution" ? 0 : 1] ?? -1;
  const sortedItems = run.items
    .slice()
    .sort((a, b) => itemScore(b[0]) - itemScore(a[0]) || a[0].localeCompare(b[0]));

  return (
    <Stack gap={20}>
      <Stack gap={6}>
        <H1>{specTitle} Paladin, 5 целей</H1>
        <Text tone="secondary">
          {chosenSpec === "retribution"
            ? "Sunken City v2.5.2a · уровень 6 · 30 секунд · набор топ-79 и Mind Amplifier · eseid-main 0–210 417 668, ошибок 0 · eseid-notebook 210 417 669–280 556 891, ошибок 0"
            : "Sunken City v2.5.2a · уровень 6 · 30 секунд · eseid-main · чанки 0–612 734 667 · ошибок в файле 0"}
        </Text>
      </Stack>

      <Row gap={8} wrap>
        <Pill active={chosenSpec === "retribution"} onClick={() => setSpec("retribution")}>Retribution</Pill>
        <Pill active={chosenSpec === "protection"} onClick={() => setSpec("protection")}>Protection</Pill>
      </Row>
      <Row gap={8} wrap>
        <Pill active={true}>5 целей</Pill>
      </Row>
      <Row gap={8} wrap>
        {available.map(([id, label]) => (
          <Pill active={chosenPool === id} onClick={() => setPool(id)}>{label}</Pill>
        ))}
      </Row>
      {ranks.length > 1 ? (
        <Row gap={8} wrap>
          {ranks.map((id) => {
            const place = id.split("|")[2];
            return (
              <Pill active={chosenRank === place} onClick={() => setRank(place)}>
                {`${place} · ${RUNS[id].dps}`}
              </Pill>
            );
          })}
        </Row>
      ) : null}

      <Grid columns={5} gap={16}>
        <Stat value={run.dps} label="DPS" tone="success" />
        <Stat value={run.total} label="Урон за 30 с" />
        <Stat value={run.crit} label="Крит" />
        <Stat value={run.strength} label="Сила" />
        <Stat value={run.manaLeft} label="Мана в конце" />
      </Grid>
      {run.farm !== run.dps ? (
        <Text size="small" tone="tertiary">
          В файле фермы у этой связки {run.farm} DPS. Разбор ниже — текущий сим.
        </Text>
      ) : null}
      {run.items.some(([name]) => name === "Pipe of Deew") ? (
        <Text size="small" tone="tertiary">
          Pipe of Deew: каждый каст оглушает героя на 0,3 с. В это время нет атак и новых способностей.
        </Text>
      ) : null}

      <H2>Урон по источникам</H2>
      <BarChart
        horizontal
        height={220}
        categories={run.sources.map((row) => row[0])}
        series={[{ name: "DPS", data: run.sources.map((row) => row[1]) }]}
        valueSuffix=" DPS"
        showValues
      />
      <Text size="small" tone="tertiary">
        Ось категорий: источник урона. Ось значений: урон в секунду за 30 с. Броня манекена 15. Ранги умений 1. Пять целей стоят в одной точке на дистанции взмаха 80: молот бьёт их вместе, только пока спираль накрывает эту точку, затем та же пара ждёт 0,85 с.
      </Text>

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H3>Порядок кнопок</H3>
          <Table
            headers={["Секунда", "Способность"]}
            columnAlign={["right", "left"]}
            rows={run.actions}
            striped
          />
          <Text size="small" tone="tertiary">
            Каст 0,15 с до эффекта, затем ещё 0,30 с герой занят. В таблице все нажатия за 30 с. Чанк {run.chunk}.
          </Text>
        </Stack>
        <Stack gap={8}>
          <H3>Характеристики в бою</H3>
          <Table headers={["Параметр", "Значение"]} rows={run.stats} />
        </Stack>
      </Grid>

      <Divider />

      <H2>Предметы в связке</H2>
      <Text tone="secondary">{run.label}. {specTitle}. 5 целей. Порядок предметов — DPS этой специализации из листа.</Text>
      <Table
        headers={["Предмет", "Источник", "Описание из игры"]}
        rows={sortedItems.map(([name, sourceName, tip]) => [name, sourceName, <GameText text={tip} />])}
        striped
      />

      <Row gap={8} align="center">
        <H2>Таланты и глифы</H2>
        <Pill active={catalog === "picked"} onClick={() => setCatalog("picked")}>В связке</Pill>
        <Pill active={catalog === "all"} onClick={() => setCatalog("all")}>Все прогнанные</Pill>
      </Row>
      <Text size="small" tone="tertiary">
        Порядок — DPS выбранной специализации: один талант или один глиф, пустой инвентарь, 5 целей. В прогоне 8 талантов набора и 12 глифов.
      </Text>
      <H3>Таланты</H3>
      <Table
        headers={["Талант", specTitle, "Описание из игры"]}
        columnAlign={["left", "right", "left"]}
        rows={talentRows.map((entry) => [entry.name, dpsOf(entry).toFixed(1), <GameText text={entry.tip} />])}
        striped
        rowTone={talentRows.map((entry) => (pickedTalents.includes(entry.name) ? "success" : undefined))}
      />
      <H3>Глифы</H3>
      <Table
        headers={["Глиф", specTitle, "Описание из игры"]}
        columnAlign={["left", "right", "left"]}
        rows={glyphRows.map((entry) => [entry.name, dpsOf(entry).toFixed(1), <GameText text={entry.tip} />])}
        striped
        rowTone={glyphRows.map((entry) => (pickedGlyphs.includes(entry.name) ? "success" : undefined))}
      />
    </Stack>
  );
}
